insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0629','business','Legal forms','medium','classic','What is limited liability intended to limit?','["Owners’ personal exposure to business debts","The number of customers","Employee working hours","The price of every product"]'::jsonb,'Owners’ personal exposure to business debts','In limited-liability entities, owners generally risk their investment rather than all personal assets, subject to law and exceptions.',10,2,array['legal forms'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
