insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0985','economics','Public finance','hard','classic','What is a public good?','["A good that people cannot easily be excluded from and that one person’s use does not reduce, like street lighting","Any good sold by a government shop","A luxury good","A good that is always free of charge"]'::jsonb,'A good that people cannot easily be excluded from and that one person’s use does not reduce, like street lighting','Public goods are non-excludable and non-rival, so markets tend to underprovide them.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
